"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[4414],{22872(e,t,o){o.r(t),o.d(t,{assets:()=>h,contentTitle:()=>i,default:()=>d,frontMatter:()=>s,metadata:()=>r,toc:()=>l});var n=o(74848),a=o(28453);const s={lang:"en",title:"Conclusion: Not a Flaw",sidebar_label:"Conclusion",slug:"/who-collects-at-the-door/conclusion",description:"Looking back over this book, the people in its nine chapters are in very different situations.",keywords:["Who's Collecting at the Door","financialization","Nebula Walker"]},i=void 0,r={id:"\u8cc7\u672c\u904a\u6232\u73a9\u4ec0\u9ebc\uff08\u5be6\u4f8b\u6a94\u6848\uff1a\u904a\u6232\u696d\uff09/\u8ab0\u5728\u9580\u53e3\u6536\u9322/conclusion",title:"Conclusion: Not a Flaw",description:"Looking back over this book, the people in its nine chapters are in very different situations.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/\u8cc7\u672c\u904a\u6232\u73a9\u4ec0\u9ebc\uff08\u5be6\u4f8b\u6a94\u6848\uff1a\u904a\u6232\u696d\uff09/\u8ab0\u5728\u9580\u53e3\u6536\u9322/conclusion.md",sourceDirName:"\u8cc7\u672c\u904a\u6232\u73a9\u4ec0\u9ebc\uff08\u5be6\u4f8b\u6a94\u6848\uff1a\u904a\u6232\u696d\uff09/\u8ab0\u5728\u9580\u53e3\u6536\u9322",slug:"/who-collects-at-the-door/conclusion",permalink:"/en/docs/who-collects-at-the-door/conclusion",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{lang:"en",title:"Conclusion: Not a Flaw",sidebar_label:"Conclusion",slug:"/who-collects-at-the-door/conclusion",description:"Looking back over this book, the people in its nine chapters are in very different situations.",keywords:["Who's Collecting at the Door","financialization","Nebula Walker"]},sidebar:"docs",previous:{title:"9. One Bridge Apart",permalink:"/en/docs/who-collects-at-the-door/ch09"},next:{title:"\ud83d\udcd6 Complete Full Edition",permalink:"/en/docs/who-collects-at-the-door/full"}},h={},l=[{value:"1. Nine Situations, One Sentence",id:"1-nine-situations-one-sentence",level:2},{value:"2. Not a Flaw",id:"2-not-a-flaw",level:2},{value:"3. Two Kinds of Escape",id:"3-two-kinds-of-escape",level:2},{value:"4. Arranging Not to Need to Win",id:"4-arranging-not-to-need-to-win",level:2},{value:"5. Another Kind of Floor",id:"5-another-kind-of-floor",level:2},{value:"6. A Key",id:"6-a-key",level:2}];function c(e){const t={a:"a",h1:"h1",h2:"h2",hr:"hr",p:"p",table:"table",th:"th",thead:"thead",tr:"tr",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door",children:"\ud83d\udcd6 Who's Collecting at the Door"})," \uff5c ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/full",children:"\ud83d\udcd6 Full Edition"})]}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h1,{id:"conclusion-not-a-flaw",children:"Conclusion: Not a Flaw"}),"\n",(0,n.jsx)(t.h2,{id:"1-nine-situations-one-sentence",children:"1. Nine Situations, One Sentence"}),"\n",(0,n.jsx)(t.p,{children:"Looking back over this book, the people in its nine chapters are in very different situations."}),"\n",(0,n.jsx)(t.p,{children:'In Chapter 1, an R&D department is replaced wholesale, and those who remain no longer say "no." In Chapter 2, original flavor becomes a luxury, and fewer and fewer people remember it. In Chapter 3, every road that seems to lead out charges the same entry fee: a floor you can afford to fall onto. In Chapter 4, some people stand in a separate restaurant, others in a shared queue. In Chapter 5, the same group of people pulls together while the pie grows and fights while it empties. In Chapter 6, the numbers are right there, and everyone who can read them has a reason not to check. In Chapter 7, a guest names the contract, the company and power three times, and gets back "you don\'t have enough backbone." In Chapter 8, an article is seen by only twenty-odd people, and its writer assumes the writing is bad. In Chapter 9, a bowl of beef noodles for NT$80 is held up by an old house already paid for.'}),"\n",(0,n.jsx)(t.p,{children:"The situations differ, but the sentence that lands on the person in each of them is much the same: you're not good enough. Not hardworking enough, not tough enough, not enough backbone, not positive enough, can't keep up with the times."}),"\n",(0,n.jsx)(t.p,{children:"This book has only one thing to say: whether you can get out is not the point; not treating the structure as your own flaw is."}),"\n",(0,n.jsx)(t.h2,{id:"2-not-a-flaw",children:"2. Not a Flaw"}),"\n",(0,n.jsxs)(t.p,{children:['Being pushed out of a financialized environment doesn\'t mean you lacked ability. Often it is exactly the opposite: you were pushed out precisely because you were able to say "no," and that word is the thing the whole system needs least (see ',(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch01",children:"Chapter 1"}),")."]}),"\n",(0,n.jsxs)(t.p,{children:["The other chapters are the same. People bound by contracts can't leave, not because they are naive (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch07",children:"Chapter 7"}),"); people whose credit is taken in a company with no money to share lose it not because they can't express themselves (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch05",children:"Chapter 5"}),"); people standing in the slowed-down queue are there not because they write badly (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch08",children:"Chapter 8"}),"); people who fell and didn't get up failed to rise not because they weren't strong enough, but because there was no floor beneath them (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch09",children:"Chapter 9"}),")."]}),"\n",(0,n.jsx)(t.p,{children:"Seeing this won't change your situation. The contract is still there, the queue is still there, the rent still has to be paid. But it will change your judgment of yourself."}),"\n",(0,n.jsx)(t.p,{children:"That step looks small, but it decides every step after it. People who treat the structure as their own flaw go and buy the course, try to change their personality, compete even harder, then lose again in the next round and prove once more that they aren't good enough. People who can see the structure at least know what they're dealing with, which efforts are useful, and which only pay fees into someone else's structure."}),"\n",(0,n.jsx)(t.p,{children:"Changing your judgment is the first step toward leaving."}),"\n",(0,n.jsx)(t.h2,{id:"3-two-kinds-of-escape",children:"3. Two Kinds of Escape"}),"\n",(0,n.jsx)(t.p,{children:"So is it really impossible to escape this game through self-study and effort?"}),"\n",(0,n.jsx)(t.p,{children:"I don't believe so, though for now I can't prove it. I'm not rich; at my best I'd count as middle class. But I believe there is always a way. To answer the question, you first have to be clear about what \"escape\" means."}),"\n",(0,n.jsx)(t.p,{children:"The first kind of escape is escaping the game's scoring system: no longer measuring yourself by degrees, job grades and comparisons with your peers. This can be done, and self-study is the most powerful tool for it. Since the internet appeared, the barriers have genuinely fallen in one class of fields: those whose results can be verified directly, such as writing, analysis, programming and design. Whether you write well or judge accurately is visible to your readers; no diploma needs to vouch for it."}),"\n",(0,n.jsxs)(t.p,{children:["The second kind of escape is escaping the structural limits: financial security, class position, no longer worrying about falling. Some people achieve this through individual effort, but there is no guarantee, and it can't be copied for everyone. And new gatekeepers appear: get around the credentials, and you run into the platforms' algorithms and the allocation of attention (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch08",children:"Chapter 8"}),'). Self-study can solve "do you have the ability," but not "does anyone see you."']}),"\n",(0,n.jsxs)(t.p,{children:["Escaping completely would mean leaving every financialized company, which is almost impossible. But in reality there are many positions and many opportunities, and not every one of them stands at the step where financialization's ill effects land. Finding an old-style company that is still expanding and still has real money to share is very hard, but at least such companies exist (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch05",children:"Chapter 5"}),")."]}),"\n",(0,n.jsxs)(t.p,{children:['One more thing calls for caution: "escape through self-study and effort" is exactly the story the leek-harvesting courses sell (see ',(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch08",children:"Chapter 8"}),'). The difference is that they sell "follow me and you\'re sure to succeed"; the version that actually works comes with no guarantee and asks you to accept a different set of standards.']}),"\n",(0,n.jsx)(t.h2,{id:"4-arranging-not-to-need-to-win",children:"4. Arranging Not to Need to Win"}),"\n",(0,n.jsxs)(t.p,{children:["Chapter 3 left a question: how can people without a floor build one for themselves (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch03",children:"Chapter 3"}),")?"]}),"\n",(0,n.jsx)(t.p,{children:'I think what comes closest to the way the rich escape is not winning their money but learning their position of "not needing to win." The rich buy a safety net with assets; ordinary people can only weave themselves a smaller net out of low demands: keep the cost of living down, stay out of the arms races in consumption and education, and give yourself the means to try slowly, so that when an attempt fails, you don\'t fall through.'}),"\n",(0,n.jsx)(t.p,{children:"The one thing an individual truly controls is the ratio of the stake to the floor. If your floor is thin, don't bet big, even if the whole society's story urges you every day to get on the bus."}),"\n",(0,n.jsx)(t.p,{children:"This is not advising people to \"just not compete.\" Chapter 3 said that in a prisoner's dilemma, no one can lay down their weapons unilaterally. Lowering the stake doesn't make the game disappear; it only means that after losing once, you're still at the table."}),"\n",(0,n.jsx)(t.p,{children:"As for my own belief, it can't be proved in advance, only tested along the way. What matters is not believing \"it will definitely succeed,\" but knowing clearly what you're betting and how much you can afford to lose. A belief like that isn't blind; it is a calculated choice."}),"\n",(0,n.jsx)(t.h2,{id:"5-another-kind-of-floor",children:"5. Another Kind of Floor"}),"\n",(0,n.jsx)(t.p,{children:"The floors discussed so far have all been money: assets, savings, a property already paid off. But there is another kind of floor that money can't buy, and that doesn't take money to pass on."}),"\n",(0,n.jsx)(t.p,{children:"What my grandfather, father and older brother left me was not assets but a way of seeing the world: how to look at a business, how to look at people, how to tell whether a structure has gone wrong. They weren't always right, but many of the analyses in this book bear the marks of that way of seeing."}),"\n",(0,n.jsx)(t.p,{children:"This kind of floor is mostly passed on not by lecturing but by being around them, watching how they conducted themselves and how they made decisions. For a family with no assets to leave the next generation, it may be the only floor truly its own; and it is exactly what this game can least charge for, and least copy."}),"\n",(0,n.jsx)(t.p,{children:"If I could pass on only one thing to the next generation, it would be the question from the preface: where is the money flowing from, and to where, and who is standing at the door collecting?"}),"\n",(0,n.jsx)(t.h2,{id:"6-a-key",children:"6. A Key"}),"\n",(0,n.jsx)(t.p,{children:"Part of this book is written for my children. They are still young and can't yet follow much of it."}),"\n",(0,n.jsx)(t.p,{children:"If they read it one day, I don't want them to walk the road I walked. The world they meet will not be the one I've written down; the shops in this book will close, the companies will change their names, and even the word \"financialization\" may by then have fallen out of use. I only hope to give them one more key: to see the structure of the world clearly, and then decide for themselves whether to take part."}),"\n",(0,n.jsx)(t.p,{children:"Whether they take part or not, there is at least one thing I hope they remember: when someone tells you that you lost out because you're not good enough, don't rush to believe it. Ask first: what happened out there?"}),"\n",(0,n.jsx)(t.p,{children:"Very often, the answer has already been given three times. It's just that no one heard it."}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.table,{children:(0,n.jsx)(t.thead,{children:(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.th,{style:{textAlign:"left"},children:(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch09",children:"\u2190 Chapter 9: One Bridge Apart"})}),(0,n.jsx)(t.th,{style:{textAlign:"center"},children:(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door",children:"\ud83d\udcd6 Back to Contents"})}),(0,n.jsx)(t.th,{style:{textAlign:"right"}})]})})})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(c,{...e})}):c(e)}},28453(e,t,o){o.d(t,{R:()=>i,x:()=>r});var n=o(96540);const a={},s=n.createContext(a);function i(e){const t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);